/*
 * What the walrus says.
 *
 * Lines are picked LOCALLY from app state rather than generated by a model.
 * Two reasons: a mascot that costs money every time a page renders is a bad
 * mascot, and the live-refresh poll re-runs server components every ten
 * seconds — an API call there would be both expensive and slow.
 *
 * The pick is DETERMINISTIC for a given state (see `choose`), so he doesn't
 * blurt out a different line every poll. He changes his mind only when
 * something about the page actually changes.
 */

export type WalrusContext =
  | { page: "watchlist"; want: number; watching: number }
  | { page: "archive"; watched: number; dropped: number; films: number }
  | { page: "show"; name: string; yourProgress: number; theirProgress: number; theirName: string }
  | { page: "film"; name: string; youSeen: boolean; theySeen: boolean; theirName: string }
  | { page: "recommendations"; count: number }
  | { page: "search"; results: number; query: string };

/** Stable index from a string — same state, same line. */
function choose(options: string[], seed: string): string {
  if (options.length === 1) return options[0];
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) | 0;
  }
  return options[Math.abs(hash) % options.length];
}

export function walrusSays(ctx: WalrusContext): string {
  switch (ctx.page) {
    case "watchlist": {
      const total = ctx.want + ctx.watching;
      if (total === 0) {
        return choose(
          [
            "Empty. Vast. Like the Arctic, but with less to watch.",
            "Nothing queued up. Go on, search for something.",
            "A blank list. Full of promise, technically.",
          ],
          "empty",
        );
      }
      if (ctx.watching > 3) {
        return choose(
          [
            `${ctx.watching} on the go at once. Bold. Unfocused, but bold.`,
            `You've started ${ctx.watching} things. Finishing is also an option.`,
          ],
          `watching-${ctx.watching}`,
        );
      }
      if (ctx.want > 12) {
        return choose(
          [
            `${ctx.want} waiting. That's not a watchlist, that's a monument.`,
            `${ctx.want} unwatched. I admire the optimism.`,
          ],
          `want-${ctx.want}`,
        );
      }
      return choose(
        [
          `${total} lined up. Reasonable. Suspiciously reasonable.`,
          "Decent list. Pick one and commit.",
          "This is a manageable amount of television. Well done.",
        ],
        `ok-${total}`,
      );
    }

    case "archive": {
      if (ctx.watched === 0) {
        return "Nothing finished yet. The archive awaits its first tenant.";
      }
      if (ctx.dropped > ctx.watched) {
        return `${ctx.dropped} abandoned against ${ctx.watched} finished. Brutal, but honest.`;
      }
      if (ctx.films > 200) {
        return choose(
          [
            `${ctx.films} films. That is not a hobby, that is a condition.`,
            `${ctx.films} films in here. I've been in the sea that whole time.`,
          ],
          `films-${ctx.films}`,
        );
      }
      return choose(
        [
          `${ctx.watched} seen through to the end. That's real commitment.`,
          `${ctx.watched} in the archive. Sizeable. Like me.`,
          `${ctx.watched} down. The tusks of experience.`,
        ],
        `arch-${ctx.watched}`,
      );
    }

    case "film": {
      if (ctx.youSeen && ctx.theySeen) {
        return choose(
          ["You've both seen this one. Rate it, then.", "Seen by all parties. Verdicts?"],
          ctx.name,
        );
      }
      if (ctx.theySeen) return `${ctx.theirName} has seen this and you haven't. Awkward.`;
      if (ctx.youSeen) return `You've seen it, ${ctx.theirName} hasn't. Don't spoil it.`;
      return choose(
        ["Neither of you has seen this. An evening presents itself.", "Unwatched. Go on."],
        ctx.name,
      );
    }

    case "show": {
      const gap = ctx.theirProgress - ctx.yourProgress;
      if (gap >= 3) {
        return `${ctx.theirName} is ${gap} episodes ahead. Watching alone, are we?`;
      }
      if (gap <= -3) {
        return `You're ${Math.abs(gap)} ahead of ${ctx.theirName}. Say nothing. Spoil nothing.`;
      }
      if (ctx.yourProgress === 0) {
        return choose(
          ["Not started. The first episode is the hardest.", "Untouched. Go on then."],
          ctx.name,
        );
      }
      return choose(
        ["Nicely in step, you two.", "Both roughly level. Very civilised.", "Keeping pace. Good."],
        ctx.name,
      );
    }

    case "recommendations": {
      if (ctx.count === 0) {
        return "Nothing to suggest yet. Rate a few things and I'll have a think.";
      }
      return choose(
        [
          `${ctx.count} ideas. I've been thinking about this in the cold.`,
          `${ctx.count} suggestions. Take them or leave them.`,
          `Here's ${ctx.count} things. I have excellent taste for a marine mammal.`,
        ],
        `rec-${ctx.count}`,
      );
    }

    case "search": {
      if (ctx.results === 0) return "Nothing. Try spelling it the other way.";
      return choose(
        [`${ctx.results} matches. Pick carefully.`, "Found some. Any of these?"],
        ctx.query,
      );
    }
  }
}
